#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using CoopBeam;
public static class IllustratedWorldInstaller {
 const string Root="Assets/WorldArt/Illustrated/";
 static IllustratedWorldLibrary library;static int changed;static readonly Dictionary<string,Sprite> cache=new Dictionary<string,Sprite>();
 [MenuItem("Coop Beam/Art/Apply Illustrated Worlds")]
 public static void Apply(){
  if(EditorApplication.isPlaying)throw new InvalidOperationException("Stop Play before installing world art.");var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(original.isDirty)throw new InvalidOperationException("Save the current scene first.");string originalPath=original.path;
  cache.Clear();changed=0;Directory.CreateDirectory(Root+"Remapped");AssetDatabase.Refresh();
  string libPath=Root+"Resources/MeltWorldStyle.asset";library=AssetDatabase.LoadAssetAtPath<IllustratedWorldLibrary>(libPath);if(!library){library=ScriptableObject.CreateInstance<IllustratedWorldLibrary>();AssetDatabase.CreateAsset(library,libPath);}
  library.backgrounds=new Sprite[4];string[] worlds={"Candy","Ice","Fire","Neon"};for(int w=0;w<4;w++){var texture=Import(worlds[w]+"Background.png");library.backgrounds[w]=SaveSprite(worlds[w]+"Background",texture,new Rect(0,0,texture.width,texture.height),Vector2.one*.5f,100);var atlas=Import(worlds[w]+"Atlas.png");int columns=w==3?4:8;var frames=new Sprite[columns*4];for(int n=0;n<frames.Length;n++){int col=n%columns,row=n/columns;int x0=Mathf.RoundToInt(col*atlas.width/(float)columns),x1=Mathf.RoundToInt((col+1)*atlas.width/(float)columns),y0=Mathf.RoundToInt((3-row)*atlas.height/4f),y1=Mathf.RoundToInt((4-row)*atlas.height/4f);var rect=ColumnShape(atlas,x0,x1,row);frames[n]=SaveSprite(worlds[w]+"_"+n.ToString("00"),atlas,rect,Vector2.one*.5f,Mathf.Max(rect.width,rect.height));}if(w==0)library.candy=frames;else if(w==1)library.ice=frames;else if(w==2)library.fire=frames;else library.neon=frames;}
  EditorUtility.SetDirty(library);AssetDatabase.SaveAssets();RefreshVariants();
  // Animation assets retain their frame counts, state indices and references from prefabs.
  foreach(string guid in AssetDatabase.FindAssets("t:PixelAnimationSet")){string path=AssetDatabase.GUIDToAssetPath(guid);if(path.StartsWith(Root)||path.Contains("/Characters/")||path.Contains("GumRemix"))continue;var set=AssetDatabase.LoadAssetAtPath<PixelAnimationSet>(path);if(!set||set.hero||set.jellyStyle)continue;int world=World(path);for(int i=0;i<set.frames.Length;i++)set.frames[i]=Remap(set.frames[i],world);EditorUtility.SetDirty(set);}
  foreach(string folder in new[]{"Assets/ReinoDeChicle/0_2_Prefabs","Assets/ReinoDeHielo/0_2_Prefabs","Assets/ReinoDeFuego/0_2_Prefabs","Assets/ReinoNeon/Prefabs"})foreach(string guid in AssetDatabase.FindAssets("t:Prefab",new[]{folder})){string path=AssetDatabase.GUIDToAssetPath(guid);var prefab=PrefabUtility.LoadPrefabContents(path);try{PatchRoot(prefab,World(path));PrefabUtility.SaveAsPrefabAsset(prefab,path);}finally{PrefabUtility.UnloadPrefabContents(prefab);}}
  int scenes=0;foreach(var entry in EditorBuildSettings.scenes){if(!entry.enabled)continue;var scene=UnityEngine.SceneManagement.SceneManager.GetSceneByPath(entry.path);bool opened=!scene.IsValid()||!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(entry.path,OpenSceneMode.Additive);int world=World(entry.path);if(!entry.path.Contains("Minigames")){foreach(var root in scene.GetRootGameObjects())PatchRoot(root,world);EnsureBackdrop(scene,world);}
   foreach(var root in scene.GetRootGameObjects())foreach(var viewport in root.GetComponentsInChildren<PixelViewport>(true)){viewport.illustrated=true;viewport.paletteShader=null;EditorUtility.SetDirty(viewport);}
   EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);scenes++;if(opened)EditorSceneManager.CloseScene(scene,true);
  }
  AssetDatabase.SaveAssets();if(!string.IsNullOrEmpty(originalPath))EditorSceneManager.OpenScene(originalPath);Debug.Log("ILLUSTRATED_WORLD_ART_OK: "+scenes+" scenes, "+changed+" sprite references replaced, 4 backgrounds and 112 atlas assets.");
 }
 static int World(string path)=>path.Contains("ReinoNeon")?3:path.Contains("ReinoDeHielo")?1:path.Contains("ReinoDeFuego")?2:0;
 static Texture2D Import(string file){string path=Root+file;var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Default;i.isReadable=true;i.alphaIsTransparency=true;i.npotScale=TextureImporterNPOTScale.None;i.maxTextureSize=4096;i.mipmapEnabled=false;i.filterMode=FilterMode.Bilinear;i.textureCompression=TextureImporterCompression.Uncompressed;i.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static Sprite SaveSprite(string name,Texture2D texture,Rect rect,Vector2 pivot,float ppu){string path=Root+"Frames/"+name+".asset";var s=Sprite.Create(texture,rect,pivot,ppu,0,SpriteMeshType.FullRect);s.name=name;var old=AssetDatabase.LoadAssetAtPath<Sprite>(path);if(old){EditorUtility.CopySerialized(s,old);UnityEngine.Object.DestroyImmediate(s);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(s,path);return s;}
 static Rect OpaqueRect(Texture2D t,int x0,int y0,int x1,int y1){var pixels=t.GetPixels32();int minx=x1,miny=y1,maxx=x0,maxy=y0;for(int y=y0;y<y1;y++)for(int x=x0;x<x1;x++)if(pixels[y*t.width+x].a>160){minx=Math.Min(minx,x);maxx=Math.Max(maxx,x);miny=Math.Min(miny,y);maxy=Math.Max(maxy,y);}if(maxx<=minx||maxy<=miny)throw new Exception("Empty atlas cell "+t.name+" "+x0+","+y0);return new Rect(minx,miny,maxx-minx+1,maxy-miny+1);}
 static Sprite Remap(Sprite old,int world){if(!old)return null;string path=AssetDatabase.GetAssetPath(old);if(path.StartsWith(Root)||path.Contains("/Characters/")||path.Contains("/Minigames/")||path.Contains("Mora_Animation")||path.Contains("Lima_Animation")||path.Contains("Coral_Animation")||path.Contains("Celeste_Animation"))return old;
  string name=(path+"/"+old.name).ToLowerInvariant();Sprite source;if(name.Contains("background")||name.Contains("backdrop")||name.Contains("moonlit"))source=library.backgrounds[world];else source=library.Get(world,Index(name,world));
  string guid;long id;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(old,out guid,out id);string key=world+"_"+guid+"_"+id.ToString().Replace('-','n');Sprite result;if(cache.TryGetValue(key,out result))return result;string asset=Root+"Remapped/"+key+".asset";result=AssetDatabase.LoadAssetAtPath<Sprite>(asset);float height=Mathf.Max(.001f,old.bounds.size.y);var sprite=Sprite.Create(source.texture,source.rect,new Vector2(old.pivot.x/old.rect.width,old.pivot.y/old.rect.height),source.rect.height/height,0,SpriteMeshType.FullRect,new Vector4(source.rect.width*.15f,source.rect.height*.15f,source.rect.width*.15f,source.rect.height*.15f));sprite.name=old.name+"_Illustrated";if(result){EditorUtility.CopySerialized(sprite,result);UnityEngine.Object.DestroyImmediate(sprite);EditorUtility.SetDirty(result);}else{AssetDatabase.CreateAsset(sprite,asset);result=sprite;}cache[key]=result;changed++;return result;
 }
 static void RefreshVariants(){foreach(string path in Directory.GetFiles(Root+"Remapped","*.asset")){var parts=Path.GetFileNameWithoutExtension(path).Split('_');if(parts.Length!=3)continue;int world;long local;if(!int.TryParse(parts[0],out world)||!long.TryParse(parts[2].Replace('n','-'),out local))continue;string original=AssetDatabase.GUIDToAssetPath(parts[1]);foreach(var candidate in AssetDatabase.LoadAllAssetsAtPath(original)){var sprite=candidate as Sprite;if(!sprite)continue;string guid;long id;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(sprite,out guid,out id);if(id==local){Remap(sprite,world);break;}}}}
 // Generated rows do not land on perfect mathematical grid boundaries. Find the four dominant
 // silhouettes in each column, ignoring isolated alpha specks, and keep their top-to-bottom order.
 static Rect ColumnShape(Texture2D t,int x0,int x1,int row){var pixels=t.GetPixels32();int w=x1-x0,h=t.height;var visited=new bool[w*h];var queue=new int[w*h];var shapes=new List<KeyValuePair<int,Rect>>();for(int y=0;y<h;y++)for(int x=x0;x<x1;x++){int at=y*w+x-x0;if(visited[at]||pixels[y*t.width+x].a<160)continue;int count=1,read=0,minx=x,maxx=x,miny=y,maxy=y;queue[0]=at;visited[at]=true;while(read<count){int n=queue[read++],px=x0+n%w,py=n/w;minx=Math.Min(minx,px);maxx=Math.Max(maxx,px);miny=Math.Min(miny,py);maxy=Math.Max(maxy,py);for(int d=0;d<4;d++){int nx=px+(d==0?-1:d==1?1:0),ny=py+(d==2?-1:d==3?1:0);if(nx<x0||nx>=x1||ny<0||ny>=h)continue;int next=ny*w+nx-x0;if(visited[next]||pixels[ny*t.width+nx].a<160)continue;visited[next]=true;queue[count++]=next;}}if(count>80)shapes.Add(new KeyValuePair<int,Rect>(count,new Rect(minx,miny,maxx-minx+1,maxy-miny+1)));}var selected=shapes.OrderByDescending(s=>s.Key).Take(4).OrderByDescending(s=>s.Value.center.y).ToArray();if(selected.Length!=4)throw new Exception("Expected four dominant silhouettes in "+t.name+" column "+x0+"; found "+selected.Length);return selected[row].Value;}
 static int Index(string s,int w){
  int frame=0;var end=System.Text.RegularExpressions.Regex.Match(s,@"(\d+)$");if(end.Success)int.TryParse(end.Value,out frame);bool alternate=frame%2==1;
  if(w==3){if(s.Contains("core"))return 8+Mathf.Clamp(frame,0,3);if(s.Contains("panel"))return s.Contains("panelon")?5:4;if(s.Contains("door"))return s.Contains("dooron")?7:6;if(s.Contains("wall"))return 6;if(s.Contains("battery"))return 2;if(s.Contains("socket"))return 3;if(s.Contains("portal"))return 14;if(s.Contains("heart"))return 13;if(s.Contains("spark"))return 15;if(s.Contains("pad")||s.Contains("checkpoint"))return 12;if(s.Contains("bridge"))return 1;return 0;}
  int enemy=-1;if(w==0){if(s.Contains("candywalker"))enemy=0;else if(s.Contains("gummyjumper"))enemy=1;else if(s.Contains("toffeechaser"))enemy=2;else if(s.Contains("cocoaguard"))enemy=3;else if(s.Contains("flyinggummy"))enemy=4;else if(s.Contains("sugarcannon"))enemy=5;else if(s.Contains("kingbubble"))return new[]{6,7,14,15}[frame%4];}
  if(w==1){if(s.Contains("snowman"))enemy=0;else if(s.Contains("penguin"))enemy=1;else if(s.Contains("owl"))enemy=2;else if(s.Contains("polarbear"))enemy=3;else if(s.Contains("turret"))enemy=4;else if(s.Contains("imp"))enemy=5;else if(s.Contains("cencellon"))return new[]{6,7,14,15}[frame%4];}
  if(w==2){if(s.Contains("kiln"))enemy=0;else if(s.Contains("salamander"))enemy=1;else if(s.Contains("fuseimp"))enemy=2;else if(s.Contains("beetle"))enemy=3;else if(s.Contains("phoenix"))enemy=4;else if(s.Contains("flower"))enemy=5;else if(s.Contains("brontoforno"))return new[]{6,7,14,15}[frame%4];}if(enemy>=0)return enemy+(alternate?8:0);
  if(s.Contains("spring")||s.Contains("jelly")||s.Contains("bounce"))return 18;if(s.Contains("crack")||s.Contains("brittle")||s.Contains("crumb"))return 19;if(s.Contains("chocolate")||s.Contains("cocoa")||s.Contains("belt"))return 17;if(s.Contains("marshmallow"))return 19;if(s.Contains("lollipop"))return 20;if(s.Contains("cane"))return 21;if(s.Contains("cloud"))return 23;if(s.Contains("bush")||s.Contains("sprout"))return 22;if(s.Contains("tree")||s.Contains("pine"))return 20;if(s.Contains("crystal"))return 21;if(s.Contains("bridge"))return 24;if(s.Contains("bubble"))return 25;if(s.Contains("heart"))return 28;if(s.Contains("gate")||s.Contains("portal"))return 29;if(s.Contains("switch")||s.Contains("plate")||s.Contains("mark"))return frame%2==0?30:31;if(s.Contains("projectile")||s.Contains("pearl")||s.Contains("snowball"))return 26;if(s.Contains("spark")||s.Contains("mote")||s.Contains("core")||s.Contains("star"))return 27;return 16;
 }
 static void PatchRoot(GameObject root,int world){
  foreach(var c in root.GetComponentsInChildren<Component>(true)){if(!c||c is Transform||c is Collider2D||c is Rigidbody2D)continue;var renderer=c as SpriteRenderer;Vector2 size=Vector2.zero;bool fit=renderer&&renderer.sprite;if(fit)size=Vector2.Scale(renderer.sprite.bounds.size,renderer.transform.localScale);
   var data=new SerializedObject(c);var p=data.GetIterator();bool has=false;while(p.Next(true)){if(p.propertyType!=SerializedPropertyType.ObjectReference)continue;var sprite=p.objectReferenceValue as Sprite;if(!sprite)continue;var mapped=Remap(sprite,world);if(mapped!=sprite){p.objectReferenceValue=mapped;has=true;}}if(has){data.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(c);}
   if(renderer&&has){if(renderer.drawMode==SpriteDrawMode.Simple&&fit&&!renderer.GetComponent<Collider2D>()){var scale=renderer.transform.localScale;scale.x=size.x/renderer.sprite.bounds.size.x;scale.y=size.y/renderer.sprite.bounds.size.y;renderer.transform.localScale=scale;}else if(renderer.drawMode!=SpriteDrawMode.Simple)renderer.drawMode=SpriteDrawMode.Sliced;var col=renderer.color;renderer.color=new Color(1,1,1,col.a);}
   if(renderer&&fit&&!renderer.GetComponentInParent<EnemyBase>()&&!renderer.GetComponentInParent<PlayerController2D>()&&renderer.GetComponentInParent<Collider2D>()&&!renderer.GetComponent<Collider2D>()&&renderer.drawMode==SpriteDrawMode.Simple){renderer.drawMode=SpriteDrawMode.Sliced;renderer.size=size;renderer.transform.localScale=Vector3.one;}
  }
  foreach(var enemy in root.GetComponentsInChildren<EnemyBase>(true))if(enemy.visual){var scale=enemy.visual.localScale;enemy.visual.localScale=new Vector3(Mathf.Abs(scale.y)*Mathf.Sign(scale.x),scale.y,scale.z);if(!enemy.visual.GetComponent<IllustratedMotion>())enemy.visual.gameObject.AddComponent<IllustratedMotion>();}
 }
 static void EnsureBackdrop(UnityEngine.SceneManagement.Scene scene,int world){foreach(var root in scene.GetRootGameObjects())foreach(var r in root.GetComponentsInChildren<SpriteRenderer>(true)){if(world==3&&r.name=="Fondo / banco tecnologico")r.enabled=false;if(r.name=="Illustrated panorama"&&world==3){r.transform.localScale=new Vector3(30/r.sprite.bounds.size.x,18/r.sprite.bounds.size.y,1);if(!r.GetComponent<IllustratedBackdrop>())r.gameObject.AddComponent<IllustratedBackdrop>();}if(r.sortingOrder<=-20&&(r.name.ToLowerInvariant().Contains("backdrop")||r.name.ToLowerInvariant().Contains("background"))){Vector3 size=r.bounds.size;r.sprite=library.backgrounds[world];r.transform.localScale=new Vector3(size.x/r.sprite.bounds.size.x,size.y/r.sprite.bounds.size.y,1);r.color=Color.white;}}
  // The long exploration maps need a continuous distant panorama behind their modular foreground.
  foreach(var root in scene.GetRootGameObjects())if(root.GetComponentInChildren<NeonLevel>(true)||root.GetComponentInChildren<BubblegumLevel>(true)){if(GameObject.Find("Illustrated panorama"))break;var g=new GameObject("Illustrated panorama");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(g,scene);var r=g.AddComponent<SpriteRenderer>();r.sprite=library.backgrounds[world];r.sortingOrder=-80;g.transform.position=world==3?new Vector3(26,3,0):new Vector3(0,28,0);g.transform.localScale=new Vector3((world==3?100:32)/r.sprite.bounds.size.x,(world==3?18:80)/r.sprite.bounds.size.y,1);break;}
 }
}
#endif
